#include <stdio.h>
#include <stdbool.h>

#define CAP 100

typedef struct {
    int data[CAP];
    int top;            /* index of top element, -1 when empty */
} Stack;

void init(Stack *s)           { s->top = -1; }
bool is_empty(const Stack *s) { return s->top == -1; }
bool is_full(const Stack *s)  { return s->top == CAP - 1; }

bool push(Stack *s, int x) {
    if (is_full(s)) return false;       /* overflow */
    s->data[++s->top] = x;
    return true;
}

bool pop(Stack *s, int *out) {
    if (is_empty(s)) return false;      /* underflow */
    *out = s->data[s->top--];
    return true;
}

bool peek(const Stack *s, int *out) {
    if (is_empty(s)) return false;
    *out = s->data[s->top];
    return true;
}

int main(void) {
    Stack s; init(&s);
    int v;
    push(&s, 10); push(&s, 20); push(&s, 30);
    pop(&s, &v);  printf("%d\n", v);   /* 30 */
    peek(&s, &v); printf("%d\n", v);   /* 20 */
    return 0;
}

int push_grow(int **a, int *cap, int *top, int x) {
    if (*top + 1 == *cap) {
        int *n = realloc(*a, (size_t)(*cap) * 2 * sizeof **a);
        if (!n) return -1;          /* old buffer still valid */
        *a = n; *cap *= 2;
    }
    (*a)[++*top] = x;
    return 0;
}

typedef struct Node { int val; struct Node *next; } Node;

int push(Node **head, int x) {
    Node *n = malloc(sizeof *n);
    if (!n) return -1;
    n->val = x; n->next = *head; *head = n;
    return 0;
}
int pop(Node **head, int *out) {
    if (!*head) return -1;
    Node *t = *head;
    *out = t->val; *head = t->next;
    free(t);
    return 0;
}

int balanced(const char *s) {
    char st[256]; int top = -1;
    for (; *s; s++) {
        char c = *s;
        if (c == '(' || c == '[' || c == '{') {
            if (top == 255) return 0;
            st[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top < 0) return 0;
            char o = st[top--];
            if ((c == ')' && o != '(') || (c == ']' && o != '[') ||
                (c == '}' && o != '{')) return 0;
        }
    }
    return top == -1;
}

/* next greater element, -1 if none */
void nge(const int *a, int n, int *res) {
    int st[1000], top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && a[st[top]] < a[i])
            res[st[top--]] = a[i];
        st[++top] = i;
    }
    while (top >= 0) res[st[top--]] = -1;
}
